              {/capture}
              {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
            {/capture}
            {=og_include('compose/Stack.latte', ['gap' => '0', 'class' => 'border-b border-border pb-2', 'children' => (string) $c_3])|noescape}
            {capture $c_10}
              {foreach og_l($v_dishes) as $v_d}
                {if og_t(og_eq(og_get($v_d, ['tag']), og_get($v_s, ['key'])))}
                  {capture $c_9}
                    {capture $c_7}
                      {capture $c_4}
